-- The maps of the five Central Florida venues (Sean, 2026-10-29: the seating charts he sent as screenshots), read the same way as
-- Hard Rock Stadium's: each level's sections clockwise by side (top left to right, right top to bottom, bottom right to left, left
-- bottom to top). We draw our own map; only the numbers come from the charts. Inter&Co Stadium is a soccer pitch; its supporters'
-- end (the right side) has no numbered sections. Suites, nests and party decks are left off.

update public.ve_venues set layout = '{"field": "football", "ring_m": 900, "levels": [{"level": "100", "name": "100 level", "sides": {"top": ["129", "131", "132", "133", "134", "135", "136", "137", "139"], "tr": ["141", "143", "144", "145"], "right": ["146", "147", "148", "149"], "br": ["151"], "bottom": ["103", "105", "106", "107", "108", "109", "110", "111"], "bl": ["113", "117"], "left": ["119", "120", "121", "122"], "tl": ["123", "125", "126", "127"]}}, {"level": "P", "name": "Plaza level (P and C sections)", "sides": {"top": ["P28", "P29", "P31", "C32", "C33", "C34", "C35", "C36", "P37", "P39", "P40"], "tr": ["P42", "P43"], "right": ["P44", "P45", "P46", "P47", "P48", "P49", "P50"], "br": ["P51", "P52", "P1", "P2"], "bottom": ["P3", "P5", "P6", "C6", "C7", "C8", "C9", "C10", "P10", "P11", "P13"], "bl": ["P15", "P16"], "left": ["P18", "P19", "P20", "P21", "P22", "P23", "P24"], "tl": ["P25", "P26"]}}, {"level": "200", "name": "200 level", "sides": {"top": ["229", "230", "231", "232", "233", "234", "235", "236", "237", "238", "239"], "tr": ["240", "241"], "br": ["202", "203"], "bottom": ["204", "205", "206", "207", "208", "209", "210", "211", "212"], "bl": ["213", "214"], "tl": ["227", "228"]}}]}'::jsonb where slug = 'camping-world-stadium';
